mapper.select:
SELECT a.id,a.task_id,a.user_id,a.subject_type,a.person_id,a.assigned_at FROM learning_task_assignment a WHERE
((a.subject_type='ACCOUNT' AND a.user_id=#{user}) OR (a.subject_type='PERSON' AND EXISTS(SELECT 1 FROM person_account_binding b JOIN person_profile p ON p.id=b.person_id WHERE b.person_id=a.person_id AND b.user_id=#{user} AND b.status='ACTIVE' AND p.status='ACTIVE')))
AND progress=#{progress}
AND (assigned_at < #{before} OR (assigned_at=#{before} AND id < #{beforeId}))
ORDER BY assigned_at DESC,id DESC LIMIT #{limit}

mapper.sql:
task_id=#{task}
AND allocation_status=#{allocation}
AND progress=#{progress}
AND user_id=#{user}

mapper.select:
SELECT s.id FROM learning_task_submission s JOIN learning_task_assignment a ON a.id=s.assignment_id AND a.task_id=s.task_id
JOIN learning_task t ON t.id=s.task_id WHERE 
ORDER BY s.submitted_at DESC,s.id DESC LIMIT #{limit} OFFSET #{offset}
